    @Component
    public static class FreteGratis implements Cupom {
        @Override
        public String codigo() {
            return "FRETEGRATIS";
        }

        @Override
        public Optional<BigDecimal> desconto(Contexto c) {
            if ("RETIRADA_LOJA".equals(c.modalidade())) {
                return Optional.empty();
            }
            return Optional.of(c.frete());
        }
