    @Test
    void vetorDaRfc7677() throws Exception {
        Class<?> tipo = Class.forName("com.loja.persistencia.Scram");
        var construtor = tipo.getDeclaredConstructor(String.class, String.class, String.class);
        construtor.setAccessible(true);
